1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	};
6	
7	export type Damage = {
8	  itemType: string;
9	  amount: number;
10	};
11	
12	export type Incident = {
13	  cause: string;
14	  damages: Damage[];
15	};
16	
17	export type Step = {
18	  op: string;
19	  items?: Item[];
20	  policy?: number;
21	  incident?: Incident;
22	};
23	
24	export type Customer = {
25	  yearsWithMHPCO: number;
26	};
27	
28	export type Scenario = {
29	  customer: Customer;
30	  steps: Step[];
31	};
32	
33	export type QuoteResult = {
34	  premium: number;
35	};
36	
37	export type ClaimResult = {
38	  payout: number;
39	  remainingCap: number;
40	};
41	
42	export type Result = QuoteResult | ClaimResult;
43	
44	export type ScenarioOutcome = {
45	  results: Result[];
46	};
47	
48	const PROCESSING_FEE = 5;
49	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
50	  sword: 100,
51	  amulet: 60,
52	  staff: 80,
53	  potion: 40,
54	  rune: 25,
55	  moonstone: 25,
56	};
57	
58	// Percentages are applied as the exact fraction `amount * percent / 100`
59	// rather than via a float factor such as `amount * 0.1`, which drifts.
60	const percentOf = (percent: number, amount: number): number =>
61	  (amount * percent) / 100;
62	
63	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
64	const CURSE_SURCHARGE_PERCENT = 50;
65	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
66	const HIGH_ENCHANTMENT_THRESHOLD = 5;
67	
68	const firstInsuranceSurchargeOn = (policyBasePremium: number): number =>
69	  percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium);
70	
71	const LOYALTY_DISCOUNT_PERCENT = 20;
72	const LOYALTY_YEARS_THRESHOLD = 2;
73	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
74	
75	// Discounts attached to the policy are percentages of the policy base premium,
76	// so they can be summed as percentages and applied in one go.
77	const policyDiscountsOn = (
78	  policyBasePremium: number,
79	  customer: Customer,
80	  contractsAlreadyIssued: number,
81	): number => {
82	  const loyaltyPercent =
83	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
84	      ? LOYALTY_DISCOUNT_PERCENT
85	      : 0;
86	  const followUpPercent =
87	    contractsAlreadyIssued > 0 ? FOLLOW_UP_DISCOUNT_PERCENT : 0;
88	  return percentOf(loyaltyPercent + followUpPercent, policyBasePremium);
89	};
90	
91	// Surcharges attached to a single item are a percentage of that item's own
92	// base premium from the price list (never of the policy base premium).
93	const surchargeForItem = (item: Item): number => {
94	  const cursePercent = item.cursed ? CURSE_SURCHARGE_PERCENT : 0;
95	  const highEnchantmentPercent =
96	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
97	      ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT
98	      : 0;
99	  return percentOf(
100	    cursePercent + highEnchantmentPercent,
101	    BASE_PREMIUM_BY_TYPE[item.type],
102	  );
103	};
104	
105	const itemSurchargesOf = (items: Item[]): number =>
106	  items.reduce((total, item) => total + surchargeForItem(item), 0);
107	
108	const BLOCK_SIZE = 3;
109	const BLOCK_BASE_PREMIUM = 60;
110	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
111	
112	const countByType = (items: Item[]): Map<string, number> => {
113	  const counts = new Map<string, number>();
114	  for (const item of items) {
115	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
116	  }
117	  return counts;
118	};
119	
120	// A group of exactly BLOCK_SIZE alike components forms a block and is charged
121	// a flat BLOCK_BASE_PREMIUM instead of the per-item price list rate. Main
122	// items never form a block.
123	const basePremiumForAlikeItems = (type: string, count: number): number =>
124	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE
125	    ? BLOCK_BASE_PREMIUM
126	    : count * BASE_PREMIUM_BY_TYPE[type];
127	
128	// An item that is not on the price list cannot be quoted; rejecting it keeps a
129	// typo from silently becoming a NaN premium.
130	const rejectUnknownItemTypes = (items: Item[]): void => {
131	  for (const item of items) {
132	    if (!(item.type in BASE_PREMIUM_BY_TYPE)) {
133	      throw new Error(`unknown item type: ${item.type}`);
134	    }
135	  }
136	};
137	
138	const policyBasePremiumOf = (items: Item[]): number =>
139	  [...countByType(items)].reduce(
140	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
141	    0,
142	  );
143	
144	// The processing fee is added after every percentage modifier, so it is never
145	// itself discounted. Only the final premium is rounded, and always up.
146	const premiumFor = (
147	  items: Item[],
148	  customer: Customer,
149	  contractsAlreadyIssued: number,
150	): number => {
151	  rejectUnknownItemTypes(items);
152	  const policyBasePremium = policyBasePremiumOf(items);
153	  const surcharges =
154	    itemSurchargesOf(items) + firstInsuranceSurchargeOn(policyBasePremium);
155	  const discounts = policyDiscountsOn(
156	    policyBasePremium,
157	    customer,
158	    contractsAlreadyIssued,
159	  );
160	  return Math.ceil(
161	    policyBasePremium + surcharges - discounts + PROCESSING_FEE,
162	  );
163	};
164	
165	const DEDUCTIBLE = 100;
166	const CAP_MULTIPLIER = 2;
167	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
168	  sword: 1000,
169	  amulet: 600,
170	  staff: 800,
171	  potion: 400,
172	  rune: 250,
173	  moonstone: 250,
174	};
175	
176	// The cap is twice the insurance sum of the policy's items, taken from the
177	// unmodified insurance values in the price list.
178	const insuranceSumOf = (items: Item[]): number =>
179	  items.reduce((total, item) => total + INSURANCE_VALUE_BY_TYPE[item.type], 0);
180	
181	const HALF_REIMBURSEMENT_PERCENT = 50;
182	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
183	
184	// The reimbursement rate of a damage depends on the damaged item itself, so
185	// the damage entry is matched against the insured items of its policy.
186	const reimbursableAmountFor = (damage: Damage, item: Item): number =>
187	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
188	    ? percentOf(HALF_REIMBURSEMENT_PERCENT, damage.amount)
189	    : damage.amount;
190	
191	const payoutForDamage = (damage: Damage, items: Item[]): number => {
192	  const item = items.find(({ type }) => type === damage.itemType) as Item;
193	  return reimbursableAmountFor(damage, item) - DEDUCTIBLE;
194	};
195	
196	// The cap belongs to the policy, not to the single claim, so successive claims
197	// on the same policy share it and each payout is clamped to what is left.
198	const claimResultFor = (
199	  damages: Damage[],
200	  insuredItems: Item[],
201	  capAlreadyConsumed: number,
202	): ClaimResult => {
203	  const remainingCapBefore =
204	    CAP_MULTIPLIER * insuranceSumOf(insuredItems) - capAlreadyConsumed;
205	  const reimbursable = damages.reduce(
206	    (total, damage) => total + payoutForDamage(damage, insuredItems),
207	    0,
208	  );
209	  const payout = Math.floor(Math.min(reimbursable, remainingCapBefore));
210	  return { payout, remainingCap: remainingCapBefore - payout };
211	};
212	
213	// Only a quote issues a contract; a claim step is not a contract and must not
214	// advance the count the follow-up discount is based on.
215	const issuesContract = (step: Step): boolean => step.op !== "claim";
216	
217	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
218	  const capConsumedByPolicy = new Map<number, number>();
219	  let contractsAlreadyIssued = 0;
220	  const results = scenario.steps.map((step) => {
221	    if (issuesContract(step)) {
222	      const premium = premiumFor(
223	        step.items ?? [],
224	        scenario.customer,
225	        contractsAlreadyIssued,
226	      );
227	      contractsAlreadyIssued += 1;
228	      return { premium };
229	    }
230	    const policyIndex = step.policy ?? 0;
231	    const capAlreadyConsumed = capConsumedByPolicy.get(policyIndex) ?? 0;
232	    const result = claimResultFor(
233	      step.incident?.damages ?? [],
234	      scenario.steps[policyIndex].items ?? [],
235	      capAlreadyConsumed,
236	    );
237	    capConsumedByPolicy.set(policyIndex, capAlreadyConsumed + result.payout);
238	    return result;
239	  });
240	  return { results };
241	};
