const payoutForDamage = (damage: Damage, items: Item[]): number => {
  const item = items.find(({ type }) => type === damage.itemType);
  if (item === undefined) {
    throw new Error(`item type not covered by the policy: ${damage.itemType}`);
  }
  return reimbursableAmountFor(damage, item) - DEDUCTIBLE;
};

